const D = { energy:.6, scale:1, density:.5, speed:1, hue:36, fold:8, pocket:.6, bloom:.5, x:.5, y:.5, style:'plaster', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const trb  = (S.tb = (S.tb||0)*.87 + (A.treble||0)*.13);

const ax = cl(P.x,.2,.8)*width, ay = cl(P.y,.2,.8)*height;
const corner = Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay));

// ---- the vault ------------------------------------------------------------
// Looking straight up into the crown of a muqarnas dome. A point at polar angle
// phi off the zenith of a hemisphere projects orthographically to radius
// R*sin(phi) -- so equal-angle tiers COMPRESS toward the rim exactly the way a
// real vault foreshortens. The tiers breathe, the light rakes around the dome,
// and a bloom climbs outward through the honeycomb.
const NF = cl(Math.round(P.fold), 5, 14)|0;
const TN = cl(3 + Math.round(cl(P.density,0,1)*3), 3, 6);
const Rmax = corner * (.75 + .55*cl(P.scale,.5,2.0));
const breath = 1 + .045*Math.sin(K.t*.071*sp) + .028*Math.sin(K.t*.157*sp+1.9) + .02*bass;
const rot = K.t*.0165*sp + .09*Math.sin(K.t*.0631+.8);

const RR = [];
for (let t=0;t<=TN;t++) RR[t] = Rmax * Math.sin(Math.PI*.5*(t/TN)) * breath;

// orbiting raking light -- the single most important thing about muqarnas
const lang = K.t*.096*sp + .55*Math.sin(K.t*.0337+2.0);
const bloomT = K.t*(.42 + .85*sp) + .7*Math.sin(K.t*.051);

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function grd(){
  if (sty==='gilt')  return [238, 72, 9];
  if (sty==='tile')  return [202, 66, 12];
  if (glow)          return [(H+194)%360, 58, 4];
  if (sty==='stone') return [38, 6, 14];
  return [(H+6)%360, 34, 11];
}
function cellCol(q, lam, bl, face){
  // q = tier depth 0..1, lam = light 0..1, bl = bloom, face = 0 rim /1 pocket /2 core
  const v = (.20 + .74*lam)*(.6+.5*en) + bl*.5;
  if (sty==='gilt')  return [ (44 + q*10 - face*4)%360, cl(72 - 26*lam - face*8, 10, 96), cl((16 + 84*v)*(face===1?.5:face===2?1.22:1), 3, 100) ];
  if (sty==='tile')  return [ [196, 178, 42][face], cl(78 - 30*lam, 12, 96), cl((14 + 82*v)*(face===1?.46:face===2?1.2:1), 3, 100) ];
  if (glow)          return [ (H + 140 + q*90 + face*30)%360, 44, cl((18 + 86*v)*(face===1?.4:face===2?1.3:1), 2, 100) ];
  if (sty==='stone') return [ 36, cl(8 - face*2, 0, 26), cl((10 + 84*v)*(face===1?.46:face===2?1.18:1), 2, 96) ];
  return [ (H + 2 + q*12 - face*3)%360, cl(30 - 12*lam - face*6, 4, 70), cl((14 + 84*v)*(face===1?.48:face===2?1.2:1), 3, 100) ];
}

const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);

let cells = 0;
for (let t=1;t<=TN;t++) cells += NF*Math.ceil(t*.5);
const rich = cells < 120;

push(); translate(ax, ay); rotate(rot);
strokeJoin(ROUND);
const jw = (u/900)*(.6 + 1.9*en);

for (let t=1; t<=TN; t++){
  const ri = RR[t-1], ro = RR[t];
  const ct = NF*Math.ceil(t*.5);
  const dth = Math.PI/ct, q = (t-1)/Math.max(1,TN-1);
  const stag = (t%2) ? .5 : 0;
  const rm = ri + (ro-ri)*.44;
  for (let k=0;k<ct;k++){
    const th = (k + stag)*2*Math.PI/ct;
    const lam = cl(.5 + .5*Math.cos(th + rot - lang), 0, 1);
    const bl = cl(P.bloom,0,1) * Math.pow(Math.max(0, Math.sin(t*1.15 - bloomT + .6*Math.sin(th*2+K.t*.11))), 3) * (.6+.5*bass) * lift;
    const jit = fr(t*31.1 + k*7.9);
    // the cell: a pointed niche opening outward, arced along the rim
    const PT = [];
    PT.push(ri, th);
    PT.push(rm, th - dth*.94);
    for (let s=0;s<=3;s++) PT.push(ro, th - dth*.52 + (dth*1.04)*(s/3));
    PT.push(rm, th + dth*.94);
    const cxr = (ri*.28 + rm*.34 + ro*.38), cyt = th;
    const drawRing = (kk, face) => {
      beginShape();
      for (let s=0;s<PT.length;s+=2){
        const rr = cxr + (PT[s]-cxr)*kk, tt = cyt + (PT[s+1]-cyt)*kk;
        vertex(rr*Math.cos(tt), rr*Math.sin(tt));
      }
      endShape(CLOSE);
    };
    const c0 = cellCol(q, lam, bl, 0);
    fill(c0[0], c0[1], c0[2], glow ? cl(30+56*lam+40*bl, 12, 96) : 100);
    stroke(gc[0], cl(gc[1]*1.2,0,100), cl(gc[2]*(.5+.5*(1-en)),0,100), 82);
    strokeWeight(jw);
    drawRing(1, 0);
    if (rich) {
      // the pocket: two nested facets sinking the cell back up into the vault
      const dp = .40 + .34*cl(P.pocket,0,1);
      const c1 = cellCol(q, lam, bl, 1);
      noStroke();
      fill(c1[0], c1[1], c1[2], glow ? cl(20+40*lam,8,80) : 100);
      drawRing(1-dp*.52, 1);
      const c2 = cellCol(q, lam*(.55+.5*jit), bl, 2);
      fill(c2[0], c2[1], cl(c2[2]*(.85+.3*trb),0,100), glow ? cl(28+56*lam,10,92) : 100);
      drawRing(1-dp*.84, 2);
    }
  }
  // tier rib
  noFill();
  stroke(gc[0], cl(gc[1]*.7,0,100), cl(gc[2] + 30 + 30*en, 0, 100), 30 + 26*en);
  strokeWeight(jw*.9);
  beginShape();
  for (let s=0;s<=48;s++){ const tt=s/48*Math.PI*2; vertex(ro*Math.cos(tt), ro*Math.sin(tt)); }
  endShape(CLOSE);
}

// ---- the oculus / crown rosette ------------------------------------------
const r0 = RR[0] + Rmax*.055;
for (let i=4;i>=0;i--){
  const kk = (i+1)/5, rr = r0*kk*1.5;
  const lam = cl(.5 + .5*Math.cos(rot - lang), 0, 1);
  const c = cellCol(0, lam*(.4+.5*kk), 0, i===0?2:0);
  fill(c[0], c[1], cl(c[2]*(.55+.6*kk),0,100), glow ? 60 : 100);
  stroke(gc[0], gc[1], cl(gc[2]*.6,0,100), 70); strokeWeight(jw*.8);
  beginShape();
  for (let s=0;s<NF*2;s++){
    const tt = s*Math.PI/NF + K.t*.021*sp*(i%2?1:-1);
    const rr2 = rr*((s%2) ? .58 : 1);
    vertex(rr2*Math.cos(tt), rr2*Math.sin(tt));
  }
  endShape(CLOSE);
}
pop();

// ---- moving chiaroscuro ---------------------------------------------------
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (16 + 28*en));
L.blendMode(ADD);
const plx = (.5 + .30*Math.cos(lang))*lw2, ply = (.5 + .27*Math.sin(lang))*lh2;
for (let i=0;i<9;i++){
  const q2=i/8, rr=Math.max(lw2,lh2)*(1.24-q2*.96);
  L.fill(0,0,100, (6 + 8*en + 5*bass)*(.26+.74*q2*q2));
  L.ellipse(plx, ply, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached plaster tooth -------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=420, th=280, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2300;i++){
    const rr=.4+fr(i*4.91)*1.9;
    t.fill(32, 8, 100-fr(i*6.13)*44, 50);
    t.ellipse(fr(i*2.31)*tw, fr(i*3.53+6.7)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
